        Assert.assertEquals("Hello World", result1);

        // Test multiple arguments with mixed types (Integer and String)
        String pattern2 = "Item: @, Qty: @";
        String result2 = Strings.format(pattern2, "Apple", 5);
        Assert.assertEquals("Item: Apple, Qty: 5", result2);

        // Test explicit handling of null values (substituted with "null")
        String pattern3 = "Value is @";
        String result3 = Strings.format(pattern3, (Object) null);
        Assert.assertEquals("Value is null", result3);

        // Test mixed null and non-null arguments
        String pattern4 = "First: @, Second: @";
        String result4 = Strings.format(pattern4, "NotNull", null);
        Assert.assertEquals("First: NotNull, Second: null", result4);

        // Test consecutive placeholders
        String pattern5 = "@@";
        String result5 = Strings.format(pattern5, "A", "B");
        Assert.assertEquals("AB", result5);

        // Test pattern with no placeholders (arguments are ignored)
        String pattern6 = "Static Text";
        String result6 = Strings.format(pattern6, 123, true);
